// Header
void LuaRegisterPhysicsAPI(lua_State* L);
void LuaSetPhysicsWorld(lua_State* L, PhysicsWorld* world);

// Implementation
static constexpr const char* kKey = "uz_physics_world";
static PhysicsWorld* GetSystem(lua_State* L) {
    lua_getfield(L, LUA_REGISTRYINDEX, kKey);
    auto* p = static_cast<PhysicsWorld*>(lua_touserdata(L, -1));
    lua_pop(L, 1);
    return p;
}
